import React, { useState } from 'react';
import '../styles/AuthForm.css';

const AuthPage = () => {
  const [isLogin, setIsLogin] = useState(true);

  return (
    <div className="auth-container">
      {isLogin ? (
        <div className="auth-left">
          <h2 className="auth-title">Welcome Back!</h2>
          <p className="auth-subtext">Login and keep the purring going!</p>
          <input type="email" placeholder="Email" className="auth-input" />
          <input type="password" placeholder="Password" className="auth-input" />
          <button className="auth-button">Login</button>
          <button className="switch-button" onClick={() => setIsLogin(false)}>New here? Sign Up</button>
        </div>
      ) : (
        <div className="auth-right">
          <h2 className="auth-title">Create Account</h2>
          <p className="auth-subtext">Sign up and treat your cat to premium PurrFeast meals!</p>
          <input type="text" placeholder="Name" className="auth-input" />
          <input type="email" placeholder="Email" className="auth-input" />
          <input type="password" placeholder="Password" className="auth-input" />
          <button className="auth-button">Sign Up</button>
          <button className="switch-button" onClick={() => setIsLogin(true)}>Already a member? Login</button>
        </div>
      )}
    </div>
  );
};

export default AuthPage;
